"""GWS CLI auth scope checking."""

import json
import logging
import subprocess
from dataclasses import dataclass, field

logger = logging.getLogger(__name__)

GWS_BINARY = "gws"

# Scopes required by the PA, mapped to what they enable
REQUIRED_SCOPES: dict[str, str] = {
    "https://www.googleapis.com/auth/calendar.readonly": "calendar read",
    "https://www.googleapis.com/auth/calendar.events": "calendar write",
}

# Scopes that are nice-to-have but not blocking
OPTIONAL_SCOPES: dict[str, str] = {
    "https://www.googleapis.com/auth/drive.readonly": "drive read",
    "https://www.googleapis.com/auth/documents.readonly": "docs read",
}


@dataclass
class ScopeStatus:
    """Result of checking GWS auth scopes."""

    available: bool = False
    granted_scopes: list[str] = field(default_factory=list)
    missing_required: dict[str, str] = field(default_factory=dict)
    missing_optional: dict[str, str] = field(default_factory=dict)
    error: str = ""

    @property
    def all_required_met(self) -> bool:
        return self.available and not self.missing_required

    @property
    def summary(self) -> str:
        if not self.available:
            return f"GWS CLI unavailable: {self.error}"
        if not self.missing_required:
            return "All required scopes granted"
        missing = ", ".join(self.missing_required.values())
        return f"Missing scopes: {missing}"

    @property
    def reauth_command(self) -> str:
        """Command that merges existing scopes with needed ones."""
        # Combine what's already granted with what's missing
        all_scopes = set(self.granted_scopes)
        all_scopes.update(REQUIRED_SCOPES.keys())
        # Filter to real OAuth scopes (skip 'email', 'profile', 'openid')
        oauth_scopes = sorted(s for s in all_scopes if s.startswith("https://"))
        return f"gws auth login --scopes {','.join(oauth_scopes)}"


def check_scopes() -> ScopeStatus:
    """Check GWS CLI auth status and required scopes."""
    status = ScopeStatus()

    try:
        result = subprocess.run(
            [GWS_BINARY, "auth", "status"],
            capture_output=True,
            text=True,
            timeout=10,
            check=False,
        )
    except FileNotFoundError:
        status.error = "gws binary not found"
        return status
    except subprocess.TimeoutExpired:
        status.error = "gws auth status timed out"
        return status

    if result.returncode != 0:
        status.error = f"gws auth status failed: {result.stderr.strip()[:80]}"
        return status

    # Parse JSON from stdout (skip any non-JSON prefix lines)
    try:
        data = json.loads(result.stdout)
    except json.JSONDecodeError:
        status.error = "could not parse gws auth status output"
        return status

    if not data.get("token_valid"):
        status.error = "token expired — run: gws auth login"
        return status

    status.available = True
    granted: list[str] = data.get("scopes", [])
    status.granted_scopes = granted

    for scope, label in REQUIRED_SCOPES.items():
        if scope not in granted:
            status.missing_required[scope] = label

    for scope, label in OPTIONAL_SCOPES.items():
        if scope not in granted:
            status.missing_optional[scope] = label

    return status
